begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();k text:=md5(gen_random_uuid()::text)||md5(gen_random_uuid()::text);k2 text:=md5(gen_random_uuid()::text)||md5(gen_random_uuid()::text);
 p jsonb;d jsonb;r jsonb;ob jsonb;l uuid;run uuid;checks jsonb;ctx jsonb;changed jsonb;ver integer;task jsonb;claim jsonb;
begin
 insert into auth.users values(u),(v);
 insert into private.agent_connections(user_id,name,token_hash,scopes,expires_at) values(u,'Search',k,array['workspace:read','drafts:write','preferences:write','batches:write'],now()+interval '1 hour'),(v,'Other',k2,array['workspace:read','drafts:write','preferences:write'],now()+interval '1 hour');
 p:='{"id":"general","name":"General","active":true,"filters":{"Employment":"Full-time"},"priorities":{},"instructions":"## Exceptions\nPreserve my narrative."}';
 d:=private.save_search_profile_for_owner(u,0,p);
 if (select projection->>'instructions' from public.search_documents where user_id=u and kind='profile')<>p->>'instructions' then raise exception 'Narrative lost';end if;
 ctx:=public.agent_dispatch(k,'context.versions','{}');
 p:=jsonb_build_object('kind','rules','id','shared','content','Show the actual location.','expectedVersion',0,'eventKey','rules');
 d:=public.agent_dispatch(k,'search.document.save',p);
 if public.agent_dispatch(k,'search.document.save',p)<>d then raise exception 'Document replay';end if;
 if public.agent_dispatch(k,'context.versions','{}')->>'personalVersion'=ctx->>'personalVersion' then raise exception 'Context version unchanged';end if;
 begin perform public.agent_dispatch(k,'search.document.save',jsonb_set(p,'{content}','"Changed"'));raise exception 'Changed replay accepted';exception when serialization_failure then null;end;
 begin perform public.agent_dispatch(k,'search.document.save',p||'{"eventKey":"stale"}');raise exception 'Stale document accepted';exception when serialization_failure then null;end;
 p:=jsonb_build_object('kind','portals','id','shared','content','{"tracked_companies":[{"id":"board","name":"Example","kind":"careers","careers_url":"https://example.com/careers","enabled":true,"provider":"greenhouse"}],"search_queries":["backend internships"],"title_filter":{"positive":["Engineer"],"negative":["Senior"]}}','expectedVersion',0,'eventKey','portals');
 d:=public.agent_dispatch(k,'search.document.save',p);
 perform private.save_search_targets_for_owner(u,1,'[{"id":"board","name":"Example renamed","kind":"careers","address":"https://example.com/careers"}]');
 ctx:=public.agent_dispatch(k,'search.context','{"profileId":"general"}');
 if not exists(select 1 from jsonb_array_elements(ctx->'documents') f where f->>'kind'='portals' and f#>>'{projection,search_queries,0}'='backend internships' and f#>>'{projection,tracked_companies,0,provider}'='greenhouse') then raise exception 'Legacy target update lost queries/provider';end if;
 p:='{"profileId":"general","mode":"backlog","eventKey":"run"}';
 r:=public.agent_dispatch(k,'search.run.start',p);run:=(r->>'id')::uuid;
 if (r->>'days')::integer<>30 or jsonb_array_length(r->'sources')<>2 then raise exception 'Run sources/defaults';end if;
 if public.agent_dispatch(k,'search.run.start',p)<>r then raise exception 'Start replay';end if;
 begin perform public.agent_dispatch(k,'search.run.start',p||'{"eventKey":"another"}');raise exception 'Duplicate active run';exception when serialization_failure then null;end;
 begin perform public.agent_dispatch(k2,'search.run.read',jsonb_build_object('runId',run));raise exception 'Cross owner run';exception when no_data_found then null;end;
 ob:=jsonb_build_object('sourceId','portal:board','url','https://example.com/jobs/1?utm_source=test','company','Example','title','Engineer','location','New York','checkedAt',now(),'liveness','active','evidence','Official employer page has active application form','employerPostedAt',null,'sourceListAgeDays',2,'description','Required experience and eligibility text.','requisitionId','req-1');
 p:=jsonb_build_object('runId',run,'listings',jsonb_build_array(ob),'eventKey','discovery');
 d:=public.agent_dispatch(k,'search.discoveries.save',p);l:=(d#>>'{saved,0,listingId}')::uuid;
 if public.agent_dispatch(k,'search.discoveries.save',p)<>d then raise exception 'Discovery replay';end if;
 perform public.agent_dispatch(k,'search.discoveries.save',jsonb_build_object('runId',run,'listings',jsonb_build_array(ob||'{"sourceId":"query:1","url":"https://example.com/jobs/1"}'),'eventKey','sighting'));
 if (select count(*) from public.search_listings where user_id=u)<>1 or (select count(*) from public.search_observations where user_id=u)<>2 then raise exception 'Cross-source dedup';end if;
 perform public.agent_dispatch(k,'search.discoveries.save',jsonb_build_object('runId',run,'listings',jsonb_build_array(ob||'{"url":"https://example.com/jobs/2","requisitionId":"req-2"}'),'eventKey','second-req'));
 ctx:=public.agent_dispatch(k,'search.discoveries.read',jsonb_build_object('runId',run,'limit',1));
 if ctx->>'nextOffset' is null or jsonb_array_length(ctx->'listings')<>1 or jsonb_array_length(ctx#>'{listings,0,possibleDuplicates}')<>1 then raise exception 'Paging/possible duplicate';end if;
 if exists(select 1 from public.search_observations where user_id=u and employer_posted_at is not null) then raise exception 'Invented date';end if;
 checks:='[{"requirement":"experience","status":"unknown","evidence":"Needs review"}]';
 begin perform public.agent_dispatch(k,'search.screening.save',jsonb_build_object('runId',run,'listingId',l,'expectedVersion',0,'decision','eligible','checks',checks,'explanation','Maybe','eventKey','bad-eligible'));raise exception 'Unknown eligible';exception when invalid_parameter_value then null;end;
 select jsonb_agg(jsonb_build_object('requirement',x,'status','met','evidence','Supported by candidate context and employer JD')) into checks from unnest(array['experience','graduation','availability','location','authorization','prior-application','company-limits']) x;
 d:=public.agent_dispatch(k,'search.screening.save',jsonb_build_object('runId',run,'listingId',l,'expectedVersion',0,'decision','eligible','checks',checks,'explanation','Minimum eligibility checked; preferred skills are not hard exclusions.','eventKey','eligible'));
 begin perform public.agent_dispatch(k2,'search.screening.save',jsonb_build_object('runId',run,'listingId',l,'expectedVersion',0,'decision','review-needed','checks','[]'::jsonb,'explanation','Other','eventKey','other'));raise exception 'Cross owner screening';exception when no_data_found then null;end;
 -- Profile changes do not rewrite the run snapshot or screening history.
 perform private.save_search_profile_for_owner(u,1,'{"id":"general","name":"General","active":true,"filters":{},"priorities":{},"instructions":"Changed targeting"}');
 r:=public.agent_dispatch(k,'search.run.read',jsonb_build_object('runId',run));
 if r->>'contextChanged'<>'true' then raise exception 'Context change invisible';end if;
 ver:=(r->>'version')::integer;
 begin perform public.agent_dispatch(k,'search.run.finish',jsonb_build_object('runId',run,'expectedVersion',ver,'state','completed','summary','Done','eventKey','bad-finish'));raise exception 'False complete coverage';exception when invalid_parameter_value then null;end;
 p:=jsonb_build_object('runId',run,'sourceId','portal:board','expectedVersion',0,'state','completed','checkpoint','{"lastPage":1}'::jsonb,'counts','{"found":2}'::jsonb,'coverage','exhaustive','eventKey','progress');
 d:=public.agent_dispatch(k,'search.progress',p);
 if public.agent_dispatch(k,'search.progress',p)<>d then raise exception 'Progress replay';end if;
 perform public.agent_dispatch(k,'search.progress',p||'{"sourceId":"query:1","state":"blocked","coverage":"inaccessible","blocker":"Runtime search unavailable","eventKey":"blocked"}');
 r:=public.agent_dispatch(k,'search.run.read',jsonb_build_object('runId',run));
 perform public.agent_dispatch(k,'search.run.finish',jsonb_build_object('runId',run,'expectedVersion',(r->>'version')::integer,'state','partial','summary','Portal complete; query inaccessible.','eventKey','finish'));
 task:=public.agent_dispatch(k,'search.request','{"profileId":"general","mode":"fresh","eventKey":"queued"}');
 claim:=public.agent_dispatch(k,'tasks.claim',jsonb_build_object('taskId',task->>'id'));
 claim:=public.agent_dispatch(k,'tasks.claim',jsonb_build_object('taskId',task->>'id'));
 d:=public.agent_dispatch(k,'tasks.report_result',jsonb_build_object('taskId',task->>'id','claimToken',claim->>'claim_token','expectedRevision',(claim->>'revision')::integer,'state','completed','result',jsonb_build_object('searchRunId',run,'summary','Actual partial sweep finished; query blocked.')));
 if d->>'state'<>'completed' then raise exception 'Search inbox task did not complete';end if;
 if exists(select 1 from public.applications where user_id=u) or exists(select 1 from public.job_batches where user_id=u) then raise exception 'Discovery created applications/batches';end if;
 -- UI reads/configures same boundary but cannot write execution evidence.
 perform set_config('test.uid',u::text,true);execute 'set local role authenticated';
 ctx:=public.search_action('search.context','{}');
 begin perform public.search_action('search.run.start','{}');raise exception 'UI execution bypass';exception when insufficient_privilege then null;end;
 if (select count(*) from public.search_listings)<>2 then raise exception 'Owner RLS';end if;
 begin update public.preferences set search='{}';raise exception 'Direct projection overwrite';exception when insufficient_privilege then null;end;
 begin update public.search_documents set content='forged';raise exception 'Direct document write';exception when insufficient_privilege then null;end;
 execute 'reset role';
 perform set_config('test.uid',v::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.search_listings) then raise exception 'Foreign RLS';end if;execute 'reset role';
 update private.agent_connections set scopes=array['workspace:read'] where token_hash=k;
 begin perform public.agent_dispatch(k,'search.document.save',p);raise exception 'Scope bypass';exception when insufficient_privilege then null;end;
 update private.agent_connections set revoked_at=now() where token_hash=k;
 begin perform public.agent_dispatch(k,'search.context','{}');raise exception 'Revoked search';exception when invalid_authorization_specification then null;end;
 delete from auth.users where id=u;
 if exists(select 1 from public.preferences where user_id=u) or exists(select 1 from public.search_documents where user_id=u) or exists(select 1 from public.search_runs where user_id=u) then raise exception 'Account deletion left search or preference data';end if;
end $$;
rollback;
